use crate::__cargo_equip::crates::{fastout::*, input_lite3::*, minmod::*};

pub fn solve<B: std::io::BufRead>(mut input: B) -> std::io::Result<()> {
    // Initialize.
    let mut bw = FBufWriter::new(std::io::stdout().lock());

    input! { source = &mut input,
        t: usize,
    }
    for _ in 0..t {
        input! { source = &mut input,
            n: u32, m: u32, a: u32, b: u32,
        }
        bw.u32_ln(minmod(n, m, a, b))?;
    }
    bw.flush()?;
    Ok(())
}

